# ORIGINAL: LB4 b2's rows for the six boot clauses compiled to the continuation instructions (audit D-0363 item 2); the rows are this file's own, generated by lk-channel evidence/LB4B2/gen_cb_rows.py
# test/core_lang/test_cont_boot_swipl.jl — the body of each of boot/init.pl:572 prolog_cut_to/1 (`'$cut'`), :604 reset/3 and :617 '$tbl_reset'/6
# (`'$reset'`), :626 shift/1 (`'$shift'(Ball)`), :629 shift_for_copy/1, :645 call_continuation/1 (`'$call_continuation'(TB)`) and
# boot/engines.pl:152 '$engine_yield'/2 (`'$yield'`), each as a user clause of the same body (pl-comp.c:3543-3556, 4703-4735 compile them):
#   * A PROGRAM consulted by the kernel's loader and cases `t_<id>(R)`, each wrapped in `catch(Goal, error(SsuE, _), R = raised(SsuE))`;
#     `g_cut_*` rows RUN `I_CUTCHP` (pl-vmi.c:2930-2959: the choice cut to, existence_error / type_error(choice, _)), IN ORDER in one
#     database; `rb_*` rows read the clauses back with clause/2 (pl-comp.c decompile: I_CUTCHP, I_RESET, I_YIELD, I_CALLCONT, I_SHIFT,
#     I_SHIFTCP). The compiled VM code itself is pinned, live against swipl, in test/compile/test_body_code_swipl.jl (pt7-pt10 and
#     the `\$call_continuation` / `\$shift` cells).
#   * `c_*` rows RUN I_RESET, I_SHIFT, I_SHIFTCP, I_CALLCONT, I_YIELD: the kernel raises a named error (the instruction, its pl-vmi.c
#     line, the step CONT1; the DIVERGES in src/pl-wam.jl), one fresh database per row. Their kernel pins are `_CB_CONT1_KERNEL`,
#     marked CONT1 flips: at CONT1 each becomes swipl's answer, pinned beside it in `_CB_PINNED`.
#   * Every swipl answer line is PINNED (swipl 10.1.19, this program and driver, LC_ALL=C, 2026-11-03, two runs byte-identical;
#     lk-channel evidence/LB4B2/cb_rows.out); with `swipl` on PATH the live answers are compared with the pins too.
#   * UNVERIFIED on the kernel: gate decides (a mismatch is traced to its upstream cause, not re-pinned).
using Test, LogicKernel
const LK = LogicKernel

# TERM TYPES PER CHUNK: REFERENCE — I_CUTCHP and the continuation instructions' compile side (src/pl-comp.jl, src/pl-wam.jl); every type in CI
include(joinpath(@__DIR__, "..", "term_under_test.jl"))
const _CB = lk_term_type(Union{Int64, Float64, String, BigInt, Rational{BigInt}})
_cbs(x) = lk_sym(_CB, Symbol(x))

"A term as the driver's `enc/1` writes it: `V<i>` by first occurrence, atoms by name, compounds `name(args)`."
function _cb_enc(t::_CB, seen::Vector{UInt64}=UInt64[])::String
    k = kind(t)
    if k === VAR
        i = findfirst(==(var_key(t)), seen)
        if i === nothing
            push!(seen, var_key(t))
            i = length(seen)
        end
        return "V$(i - 1)"
    elseif k === SYM
        return is_nil(t) ? "[]" : sym_text(t)
    elseif k === GND
        v = lk_value(t)
        v isa AbstractString && return "s\"" * String(v) * "\""
        v isa Integer && return "$v"
        v isa AbstractFloat && return "$v"
        return "?$(typeof(v))"
    end
    h = child(t, 1)
    return (is_nil(h) ? "[]" : sym_text(h)) * "(" *
           join([_cb_enc(child(t, i), seen) for i in 2:nchildren(t)], ",") * ")"
end

# the swipl side: the MOD3b driver (consult, then every answer of each t_<id>/1, `enc`oded)
const _CB_DRIVER = raw"""
enc(T) :- enc(T, [], _).
enc(V, S0, S) :- var(V), !, ( vidx(S0, V, 0, I) -> S = S0 ; length(S0, I), append(S0, [V], S) ), format("V~w", [I]).
enc(T, S, S) :- T == [], !, write('[]').
enc(T, S, S) :- atom(T), !, write(T).
enc(T, S, S) :- string(T), !, format("s\"~w\"", [T]).
enc(T, S, S) :- integer(T), !, format("~w", [T]).
enc(T, S, S) :- float(T), !, format("~w", [T]).
enc(T, S0, S) :- compound_name_arity(T, N, A),
    write(N), format("(", []), encargs(1, A, T, S0, S), write(')').
encargs(I, A, _, S, S) :- I > A, !.
encargs(I, A, T, S0, S) :- arg(I, T, X), enc(X, S0, S1), ( I < A -> write(',') ; true ),
    I1 is I+1, encargs(I1, A, T, S1, S).
vidx([X|_], V, I, I) :- X == V, !.
vidx([_|Xs], V, I0, I) :- I1 is I0+1, vidx(Xs, V, I1, I).
fz_pred(N) :-
    format("~w", [N]), functor(G, N, 1),
    catch(findnsols(50, G, G, Gs), _, Gs = [exception]),
    forall(member(S, Gs), ( S == exception -> write(' exception') ; write(' '), enc(S) )), nl.
fz_run(File, Ns) :-
    catch(( consult(File), S = ok ), E, S = exc(E)),
    ( S == ok -> writeln(ok) ; S = exc(B), write('exc '), enc(B), nl ),
    forall(member(N, Ns), fz_pred(N)).
"""
function _cb_swipl_lines(path::String, names::Vector{String})::Vector{String}
    out = mktempdir() do d
        f = joinpath(d, "drv.pl")
        write(
            f,
            _CB_DRIVER * ":- initialization((fz_run('$path', [" * join(names, ",") *
            "]), halt)).\n"
        )
        read(
            pipeline(addenv(`swipl -q $f`, "LC_ALL" => "C"); stdin=devnull, stderr=devnull),
            String
        )
    end
    return String.(split(chomp(out), '\n'; keepempty=false))
end

# the program: the six boot bodies as user clauses (boot/init.pl:572-645, boot/engines.pl:152 at the pin cbf4e189)
const _CB_PROGRAM = raw"""
cb_cut(_Choice) :- '$cut'.
cb_reset(_Goal, _Ball, _Cont) :- '$reset'.
cb_tbl_reset(_Goal, _Ball, _Cont, _WorkList, _Skeleton, _Delays) :- '$reset'.
cb_shift(Ball) :- '$shift'(Ball).
cb_shiftcp(Ball) :- '$shift_for_copy'(Ball).
cb_cc(TB) :- '$call_continuation'(TB).
cb_yield(_Term, _Code) :- '$yield'.
cb_mem(a).
cb_mem(b).
cb_mem(c).
"""

# (id, goal), run IN ORDER in one database: I_CUTCHP's run, then the read-backs
const _CB_CASES = [
    ("g_cut_var", raw"cb_cut(_)"),
    ("g_cut_atom", raw"cb_cut(foo)"),
    ("g_cut_float", raw"cb_cut(1.5)"),
    ("g_cut_cmp", raw"cb_cut(f(x))"),
    ("g_cut_big", raw"cb_cut(100000000000000000000)"),
    ("g_cut_neg", raw"cb_cut(-1)"),
    ("g_cut_far", raw"cb_cut(1000000)"),
    ("g_cut_live", raw"findall(X, (prolog_current_choice(Ch), cb_mem(X), cb_cut(Ch)), R)"),
    ("g_cut_own", raw"findall(X, (cb_mem(X), prolog_current_choice(Ch), cb_cut(Ch)), R)"),
    (
        "g_cut_mid",
        raw"findall(X-Y, (cb_mem(X), prolog_current_choice(Ch), cb_mem(Y), cb_cut(Ch)), R)"
    ),
    ("g_cut_det", raw"prolog_current_choice(Ch), cb_cut(Ch), R = yes"),
    (
        "g_cut_stale",
        raw"( cb_mem(_), prolog_current_choice(Ch) -> true ), catch(cb_cut(Ch), error(existence_error(choice, C), _), ( integer(C) -> R = stale_int ; R = stale(C) ))"
    ),
    (
        "g_cut_after",
        raw"findall(X, (cb_mem(X), prolog_current_choice(Ch), cb_cut(Ch), X \== a), R)"
    ),
    ("rb_cut", raw"clause(cb_cut(A), B), R = A-B"),
    ("rb_reset", raw"clause(cb_reset(A, B, C), D), R = f(A, B, C, D)"),
    (
        "rb_tbl_reset",
        raw"clause(cb_tbl_reset(A, B, C, D, E, F), G), R = f(A, B, C, D, E, F, G)"
    ),
    ("rb_shift", raw"clause(cb_shift(A), B), R = A-B"),
    ("rb_shiftcp", raw"clause(cb_shiftcp(A), B), R = A-B"),
    ("rb_cc", raw"clause(cb_cc(A), B), R = A-B"),
    ("rb_yield", raw"clause(cb_yield(A, B), C), R = f(A, B, C)")
]

# (id, goal, the kernel's refusal until CONT1): each in a database of its own (the refusal leaves the run loop)
const _CB_CONT1 = [
    (
        "c_reset",
        raw"cb_reset(true, B, C), R = B-C",
        "the VM instruction I_RESET (pl-vmi.c:5754)"
    ),
    (
        "c_reset_shift", raw"cb_reset(cb_shift(x), B, C), R = B-C",
        "the VM instruction I_RESET (pl-vmi.c:5754)"
    ),
    ("c_shift", raw"cb_shift(x)", "the VM instruction I_SHIFT (pl-vmi.c:5874)"),
    ("c_shiftcp", raw"cb_shiftcp(x)", "the VM instruction I_SHIFTCP (pl-vmi.c:5908)"),
    ("c_cc", raw"cb_cc([])", "the VM instruction I_CALLCONT (pl-vmi.c:5839)"),
    ("c_yield", raw"cb_yield(t, 256)", "the VM instruction I_YIELD (pl-vmi.c:2410)")
]

# swipl 10.1.19's answers (the driver's whole output: `ok`, then one line per case of _CB_CASES, then of _CB_CONT1)
const _CB_PINNED = [
    raw"ok",
    raw"t_g_cut_var t_g_cut_var(raised(instantiation_error))",
    raw"t_g_cut_atom t_g_cut_atom(raised(type_error(choice,foo)))",
    raw"t_g_cut_float t_g_cut_float(raised(type_error(choice,1.5)))",
    raw"t_g_cut_cmp t_g_cut_cmp(raised(type_error(choice,f(x))))",
    raw"t_g_cut_big t_g_cut_big(raised(type_error(choice,100000000000000000000)))",
    raw"t_g_cut_neg t_g_cut_neg(raised(existence_error(choice,-1)))",
    raw"t_g_cut_far t_g_cut_far(raised(existence_error(choice,1000000)))",
    raw"t_g_cut_live t_g_cut_live([|](a,[]))",
    raw"t_g_cut_own t_g_cut_own([|](a,[|](b,[|](c,[]))))",
    raw"t_g_cut_mid t_g_cut_mid([|](-(a,a),[|](-(b,a),[|](-(c,a),[]))))",
    raw"t_g_cut_det t_g_cut_det(yes)",
    raw"t_g_cut_stale t_g_cut_stale(stale_int)",
    raw"t_g_cut_after t_g_cut_after([|](b,[|](c,[])))",
    raw"t_rb_cut t_rb_cut(-(V0,$cut))",
    raw"t_rb_reset t_rb_reset(f(V0,V1,V2,$reset))",
    raw"t_rb_tbl_reset t_rb_tbl_reset(f(V0,V1,V2,V3,V4,V5,$reset))",
    raw"t_rb_shift t_rb_shift(-(V0,$shift(V0)))",
    raw"t_rb_shiftcp t_rb_shiftcp(-(V0,$shift_for_copy(V0)))",
    raw"t_rb_cc t_rb_cc(-(V0,$call_continuation(V0)))",
    raw"t_rb_yield t_rb_yield(f(V0,V1,$yield))",
    raw"t_c_reset t_c_reset(-(V0,0))",
    raw"t_c_reset_shift t_c_reset_shift(raised(existence_error(reset,x)))",
    raw"t_c_shift t_c_shift(raised(existence_error(reset,x)))",
    raw"t_c_shiftcp t_c_shiftcp(raised(existence_error(reset,x)))",
    raw"t_c_cc t_c_cc(raised(type_error(continuation,[])))",
    raw"t_c_yield t_c_yield(raised(permission_error(execute,vmi,I_YIELD)))"
]

# the kernel's pins of the c_* rows: CONT1 flips each to swipl's line in _CB_PINNED. swipl 10.1.19 answers
# c_reset `-(V0,0)` (the goal's success: Cont = 0); c_reset_shift, c_shift, c_shiftcp `existence_error(reset, x)` (a user clause of
# the reset/3 body is no reset/3 frame for findReset); c_cc `type_error(continuation, [])`; c_yield
# `permission_error(execute, vmi, 'I_YIELD')` (not an engine). UNVERIFIED on the kernel: gate decides.
const _CB_CONT1_KERNEL = [
    "t_$(id) refused $(what) CONT1" for (id, _, what) in _CB_CONT1
]

"The program and cases as one file; the case predicates' names."
function _cb_file()::Tuple{String, Vector{String}}
    all_ = [[(id, g) for (id, g) in _CB_CASES]; [(id, g) for (id, g, _) in _CB_CONT1]]
    names = ["t_$(id)" for (id, _) in all_]
    text =
        _CB_PROGRAM * join([
            "t_$(id)(R) :- catch(($g), error(SsuE, _), R = raised(SsuE)).\n" for
            (id, g) in all_
        ])
    f = joinpath(mktempdir(), "contboot.pl")
    write(f, text)
    return f, names
end

"""
The kernel's lines for `names` after consulting `path`, as the driver writes swipl's; a run that
raises the refusal exception (`LK.NotPortedError`, its `what` and `step`) writes `refused <what> <step>`.
"""
function _cb_kernel(path::String, names::Vector{String})
    gd = LK.PL_global_data{_CB}()
    ld = LK.PL_local_data{_CB}(gd)
    st, ball = LK.load_file!(gd, ld, path)
    out = [st === :ok ? "ok" : "exc " * _cb_enc(ball::_CB)]
    for name in names
        proc = LK.isCurrentProcedure(sym_key(_cbs(name)), 1, LK.MODULE_user(gd))
        if proc === nothing || !LK.isDefinedProcedure(gd, proc)
            push!(out, "$name undefined")
            continue
        end
        sols = String[]
        fid = LK.PL_open_foreign_frame(ld)
        a = LK.PL_new_term_refs(ld, 1)
        LK.putSlotValue!(ld, a + 1, mk_var(_CB, LK.fresh_var_keys!(1)), LK.PutVarMap())
        qid = LK.PL_open_query(
            gd, ld, nothing, LK.PL_Q_CATCH_EXCEPTION | LK.PL_Q_EXT_STATUS, proc, a
        )
        n = 0
        refused = nothing
        while (n += 1) <= 50
            rc = try
                LK.PL_next_solution(gd, ld, qid)
            catch e
                e isa LK.NotPortedError || rethrow()
                refused = "refused " * e.what * " " * e.step
                break
            end
            if rc == LK.PL_S_TRUE || rc == LK.PL_S_LAST
                push!(
                    sols,
                    _cb_enc(mk_expr(_CB, _CB[_cbs(name), lk_answers(ld, (a:a)...)...]))
                )
                rc == LK.PL_S_LAST && break
            elseif rc == LK.PL_S_EXCEPTION
                push!(sols, "exception")
                break
            else
                break
            end
        end
        if refused !== nothing                  # the run loop was left: the database is not reused
            push!(out, "$name " * refused)
            return out
        end
        LK.PL_close_query(ld, qid)
        LK.PL_close_foreign_frame(ld, fid)
        push!(out, "$name" * join(" " .* sols))
    end
    return out
end

@testset "I_CUTCHP runs and the six boot bodies read back as swipl's (LB4 b2)" begin
    f, names = _cb_file()
    ng = length(_CB_CASES)
    kl = _cb_kernel(f, names[1:ng])
    @test length(kl) == ng + 1
    for (k, p) in zip(kl, _CB_PINNED[1:(ng + 1)])
        k == p || println(stderr, "  ours  ", k, "\n  swipl ", p)
        @test k == p
    end
    # not vacuous: the rows answer error terms, a cut answer list, an uncut one and the read-back bodies
    @test count(l -> occursin("raised(type_error(choice,", l), _CB_PINNED) >= 4
    @test count(l -> occursin("raised(existence_error(choice,", l), _CB_PINNED) >= 2
    @test raw"t_g_cut_live t_g_cut_live([|](a,[]))" in _CB_PINNED      # the cut removed cb_mem's choice
    @test any(l -> startswith(l, "t_g_cut_own ") && occursin("(c,[])", l), _CB_PINNED)
    @test any(l -> startswith(l, "t_rb_shift ") && occursin("\$shift(V0)", l), _CB_PINNED)
end

@testset "the continuation instructions raise the named error until CONT1 (CONT1 flips)" begin
    f, names = _cb_file()
    ng = length(_CB_CASES)
    for (k, (id, _, _)) in enumerate(_CB_CONT1)
        kl = _cb_kernel(f, [names[ng + k]])     # a database of its own per row
        @test kl[1] == "ok"
        # CONT1 flips: the kernel's answer becomes swipl's, `_CB_PINNED[ng + 1 + k]`
        kl[end] == _CB_CONT1_KERNEL[k] ||
            println(stderr, "  ours  ", kl[end], "\n  pin   ", _CB_CONT1_KERNEL[k])
        @test kl[end] == _CB_CONT1_KERNEL[k]
        @test startswith(_CB_PINNED[ng + 1 + k], "t_$(id) ")
        @test _CB_PINNED[ng + 1 + k] != _CB_CONT1_KERNEL[k]     # the pin differs from swipl's: a deferral
    end
end

@testset "the pins are swipl's (live, when swipl is on PATH)" begin
    swipl = get(ENV, "LOGICKERNEL_NO_SWIPL", "") == "1" ? nothing : Sys.which("swipl")
    # the pinned table is the driver's whole output (the inert-testset guard: an assertion either way)
    @test length(_CB_PINNED) == length(_CB_CASES) + length(_CB_CONT1) + 1
    if swipl === nothing
        @info "LB4 b2 CONT-BOOT LIVE CHECK NOT RUN: `swipl` is not on PATH here. It runs in tools/run_tests.sh and CI."
    else
        f, names = _cb_file()
        @test _cb_swipl_lines(f, names) == _CB_PINNED
    end
end

# THE OPCODE ORDER (audit D-0407 item 3), type independent. The table is src/pl-vmi.jl `_CODE_TABLE` (row = code + 1); upstream's
# order is that of the `VMI(NAME, ...)` entries of pl-vmi.c at the pin: B_ARG_CF :1537, B_ARG_VF :1580, I_YIELD :2410, I_CUTCHP :2935,
# S_WRAP :3560, S_CALLWRAPPER :3624, S_TABLED :3644, I_RESET :5754, I_EXITRESET :5801, I_CALLCONT :5839, I_SHIFT :5874, I_SHIFTCP :5908.
# The whole table is not in pl-vmi.c's order (the steps before ARGINL grouped their instructions by landing: a renumber of their
# numbers is a separate decision), so the row compares the TAIL, from B_ARG_CF to the last row. Both sides come through ONE extractor
# (the names in order) and both are asserted non-empty. As test/test_vendored_swipl.jl: the checkout is always there in CI (the
# testset FAILS without it), a local run without it skips and says so.
const _CB_UP = get(
    ENV,
    "LOGICKERNEL_UPSTREAM_SWIPL_DEVEL",
    joinpath(homedir(), "dev-zone", "swipl-devel")
)
const _CB_CI = get(ENV, "CI", "") == "true"
"The instruction names of `lines`, in order: the first word of each `VMI(NAME, ...` line (pl-vmi.c) or of each `code_info(:NAME, ...` row."
function _cb_vmi_names(lines::Vector{String})::Vector{Symbol}
    out = Symbol[]
    for l in lines
        m = match(r"^VMI\((\w+),", l)
        m === nothing && (m = match(r"^\s*code_info\(:(\w+),", l))
        m === nothing || push!(out, Symbol(m.captures[1]))
    end
    return out
end
if _CB_CI || isdir(joinpath(_CB_UP, ".git"))
    @testset "the tail of the opcode table is in pl-vmi.c's order, consecutive (D-0407 item 3)" begin
        have_up = isdir(joinpath(_CB_UP, ".git"))
        have_up ||
            @error "test_cont_boot_swipl: CI must check out swipl-devel at the pinned " *
                "commit (LOGICKERNEL_UPSTREAM_SWIPL_DEVEL = $_CB_UP): none there"
        @test have_up
        if have_up
            pinline = first(
                filter(
                    l -> startswith(l, "commit:"),
                    readlines(joinpath(@__DIR__, "..", "..", "tools", "SWIPL_VERSION"))
                )
            )
            pin = String(strip(pinline[8:end]))
            @test occursin(r"^[0-9a-f]{40}$", pin)
            up = _cb_vmi_names(readlines(`git -C $_CB_UP show $pin:src/pl-vmi.c`))
            # the table's rows through the SAME extractor, read from src/pl-vmi.jl's text (`_CODE_TABLE` .. its closing paren)
            src = readlines(joinpath(@__DIR__, "..", "..", "src", "pl-vmi.jl"))
            r0 = findfirst(l -> startswith(l, "const _CODE_TABLE = ("), src)
            r1 = r0 + findfirst(==(")"), src[r0:end]) - 1
            tbl = _cb_vmi_names(src[r0:r1])
            kern = Symbol[LK._CODE_TABLE[i].name for i in 1:length(LK._CODE_TABLE)]
            @test !isempty(up) && !isempty(tbl) && !isempty(kern)
            @test kern == tbl                            # the live table is the one the text declares
            first_row = Int(LK.B_ARG_CF) + 1
            tail = kern[first_row:end]
            @test length(tail) == 12                     # B_ARG_CF .. I_SHIFTCP
            @test first(tail) == :B_ARG_CF && last(tail) == :I_SHIFTCP
            @test all(n -> n in up, tail)                 # every tail name is a VMI() entry of the pin
            @test tail == filter(n -> n in Set(tail), up) # the same names, upstream's order
            codes = [getfield(LK, n) for n in tail]
            @test all(i -> Int(codes[i]) == Int(codes[i - 1]) + 1, 2:length(codes))
            @test [LK._CODE_TABLE[Int(c) + 1].name for c in codes] == tail  # the consts and the rows agree
        end
    end
else
    @info "test_cont_boot_swipl: opcode-order row SKIPPED: no swipl-devel checkout at $_CB_UP (CI always has one)"
end
